/*=========================================================
  HELPERS
=========================================================*/
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
const finePointer = window.matchMedia("(hover:hover) and (pointer:fine)").matches;
const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const hasGSAP = typeof gsap !== "undefined" && typeof ScrollTrigger !== "undefined";
if (hasGSAP) {
    gsap.registerPlugin(ScrollTrigger);
} else {
    document.documentElement.classList.add("no-gsap");
}

/*=========================================================
  LOADER
=========================================================*/
(function loader() {
    const el = $(".loader");
    if (!el) return;
    const hide = () => el.classList.add("done");
    window.addEventListener("load", hide);
    setTimeout(hide, 5000); // never trap the visitor if a CDN is slow
})();

/*=========================================================
  SOCIAL LINKS (hide the ones that are not filled in)
=========================================================*/
$$("[data-social]").forEach(a => {
    const url = CONFIG.socials[a.dataset.social];
    if (url) a.href = url; else a.hidden = true;
});

/*=========================================================
  CUSTOM CURSOR (mouse only)
=========================================================*/
(function cursor() {
    if (!finePointer) return;
    const dot = $(".cursor-dot"), ring = $(".cursor-ring");
    if (!dot || !ring) return;
    document.body.classList.add("has-cursor");
    let mx = -100, my = -100, rx = -100, ry = -100;
    window.addEventListener("mousemove", e => {
        mx = e.clientX; my = e.clientY;
        dot.style.left = mx + "px"; dot.style.top = my + "px";
    });
    (function loop() {
        rx += (mx - rx) * 0.16; ry += (my - ry) * 0.16;
        ring.style.left = rx + "px"; ring.style.top = ry + "px";
        requestAnimationFrame(loop);
    })();
    const hoverSel = "a, button, .skill-card, .project-box, input, textarea";
    document.addEventListener("mouseover", e => { if (e.target.closest(hoverSel)) ring.classList.add("hovered"); });
    document.addEventListener("mouseout", e => { if (e.target.closest(hoverSel)) ring.classList.remove("hovered"); });
})();

/*=========================================================
  HEADER: mobile menu, sticky, active link, progress bar
=========================================================*/
(function header() {
    const menuBtn = $("#menu-icon"), icon = $("i", menuBtn), nav = $(".navbar"), bar = $(".header");
    menuBtn.addEventListener("click", () => {
        const open = nav.classList.toggle("active");
        icon.classList.toggle("bx-x", open);
        icon.classList.toggle("bx-menu", !open);
    });
    $$(".navbar a").forEach(a => a.addEventListener("click", () => {
        nav.classList.remove("active");
        icon.classList.remove("bx-x"); icon.classList.add("bx-menu");
    }));

    const progress = $(".scroll-progress");
    const onScroll = () => {
        bar.classList.toggle("sticky", window.scrollY > 100);
        const total = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        progress.style.width = (total > 0 ? (window.scrollY / total) * 100 : 0) + "%";
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    const links = $$(".navbar a");
    const io = new IntersectionObserver(entries => {
        entries.forEach(en => {
            if (!en.isIntersecting) return;
            links.forEach(l => l.classList.toggle("active", l.getAttribute("href") === "#" + en.target.id));
        });
    }, { rootMargin: "-45% 0px -50% 0px" });
    $$("section[id]").forEach(s => io.observe(s));
})();

/*=========================================================
  SMOOTH SCROLL
=========================================================*/
$$('a[href^="#"]').forEach(a => {
    a.addEventListener("click", e => {
        const id = a.getAttribute("href");
        if (!id || id.length < 2) return;
        const target = $(id);
        if (target) { e.preventDefault(); target.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth" }); }
    });
});

/*=========================================================
  HERO ENTRANCE (one choreographed sequence)
=========================================================*/
if (hasGSAP && !reduceMotion) {
    const tl = gsap.timeline({ delay: 0.3, defaults: { ease: "power3.out" } });
    tl.to(".home-content .eyebrow", { opacity: 1, y: 0, duration: 0.7 })
      .to(".home-content > h3:not(.role-line)", { opacity: 1, y: 0, duration: 0.7 }, "-=0.45")
      .to(".home-content > h1", { opacity: 1, y: 0, duration: 0.9 }, "-=0.45")
      .to(".home-content > h3.role-line", { opacity: 1, y: 0, duration: 0.7 }, "-=0.55")
      .to(".home-content > p", { opacity: 1, y: 0, duration: 0.7 }, "-=0.45")
      .to(".home-content > .social-media", { opacity: 1, y: 0, duration: 0.7 }, "-=0.4")
      .to(".home-content > .buttons", { opacity: 1, y: 0, duration: 0.7 }, "-=0.4")
      .from(".home-img", { opacity: 0, scale: 0.8, duration: 1.2, ease: "back.out(1.4)", clearProps: "opacity,transform" }, 0.4);
} else if (hasGSAP) {
    gsap.set($$(".home .reveal"), { opacity: 1, y: 0 });
}

/*=========================================================
  TYPEWRITER
=========================================================*/
(function typewriter() {
    const el = $(".multiple-text");
    if (!el) return;
    const words = ["Java Full Stack Developer", "Spring Boot Developer", "Backend Developer", "React Developer", "Oracle SQL Developer"];
    if (reduceMotion) { el.textContent = words[0]; return; }
    let w = 0, c = 0, del = false;
    (function tick() {
        const cur = words[w];
        if (!del) {
            c++;
            el.textContent = cur.slice(0, c);
            if (c === cur.length) { del = true; return setTimeout(tick, 1400); }
        } else {
            c--;
            el.textContent = cur.slice(0, c);
            if (c === 0) { del = false; w = (w + 1) % words.length; }
        }
        setTimeout(tick, del ? 50 : 100);
    })();
})();

/*=========================================================
  SCROLL REVEAL (3D tilt-up as sections arrive)
=========================================================*/
if (hasGSAP) {
    const items = $$(".reveal").filter(el => !el.closest(".home"));
    if (!reduceMotion) gsap.set(items, { rotationX: 12, transformPerspective: 1000, transformOrigin: "50% 100%" });
    ScrollTrigger.batch(items, {
        start: "top 90%",
        once: true,
        onEnter: batch => gsap.to(batch, {
            opacity: 1, y: 0, rotationX: 0,
            duration: 0.9, ease: "power3.out", stagger: 0.08,
            onComplete: () => gsap.set(batch, { transformOrigin: "50% 50%" })
        })
    });

    // timeline line draws as you scroll
    const line = $(".timeline-line");
    if (line) {
        gsap.to(line, {
            scaleY: 1, ease: "none",
            scrollTrigger: { trigger: ".timeline", start: "top 75%", end: "bottom 60%", scrub: 0.6 }
        });
    }
}

/*=========================================================
  STAT COUNTERS
=========================================================*/
(function counters() {
    const nums = $$("[data-count]");
    const finish = n => { n.textContent = n.dataset.count + (n.dataset.suffix || ""); };
    if (!hasGSAP || reduceMotion) { nums.forEach(finish); return; }
    ScrollTrigger.create({
        trigger: ".stats", start: "top 88%", once: true,
        onEnter: () => nums.forEach(n => {
            const o = { v: 0 }, target = +n.dataset.count;
            gsap.to(o, { v: target, duration: 1.8, ease: "power2.out", onUpdate: () => { n.textContent = Math.round(o.v) + (n.dataset.suffix || ""); } });
        })
    });
})();

/*=========================================================
  3D TILT (skill cards, project cards, info cards, about photo)
=========================================================*/
(function tilt() {
    if (!hasGSAP || !finePointer || reduceMotion) return;
    $$("[data-tilt]").forEach(el => {
        const max = parseFloat(el.dataset.tilt) || 10;
        const glow = $(".card-glow", el);
        let rx, ry, ly, ready = false;

        // create the tweens on first hover so they never clash with the scroll reveal
        const setup = () => {
            if (ready) return;
            ready = true;
            gsap.set(el, { transformPerspective: 900 });
            rx = gsap.quickTo(el, "rotationX", { duration: 0.5, ease: "power3.out" });
            ry = gsap.quickTo(el, "rotationY", { duration: 0.5, ease: "power3.out" });
            ly = gsap.quickTo(el, "y", { duration: 0.5, ease: "power3.out" });
        };
        el.addEventListener("pointerenter", setup);
        el.addEventListener("pointermove", e => {
            setup();
            const r = el.getBoundingClientRect();
            const px = (e.clientX - r.left) / r.width;
            const py = (e.clientY - r.top) / r.height;
            ry((px - 0.5) * max * 2);
            rx(-(py - 0.5) * max * 2);
            ly(-6);
            if (glow) { glow.style.setProperty("--mx", px * 100 + "%"); glow.style.setProperty("--my", py * 100 + "%"); }
        });
        el.addEventListener("pointerleave", () => { if (ready) { rx(0); ry(0); ly(0); } });
    });
})();

/*=========================================================
  MAGNETIC BUTTONS + RIPPLE
=========================================================*/
$$(".btn").forEach(btn => {
    btn.addEventListener("click", function (e) {
        const r = this.getBoundingClientRect();
        const ripple = document.createElement("span");
        ripple.className = "ripple";
        ripple.style.left = e.clientX - r.left + "px";
        ripple.style.top = e.clientY - r.top + "px";
        this.appendChild(ripple);
        setTimeout(() => ripple.remove(), 600);
    });
    if (hasGSAP && finePointer && !reduceMotion) {
        const xTo = gsap.quickTo(btn, "x", { duration: 0.5, ease: "power3.out" });
        const yTo = gsap.quickTo(btn, "y", { duration: 0.5, ease: "power3.out" });
        btn.addEventListener("mousemove", e => {
            const r = btn.getBoundingClientRect();
            xTo(((e.clientX - (r.left + r.width / 2)) / r.width) * 22);
            yTo(((e.clientY - (r.top + r.height / 2)) / r.height) * 22);
        });
        btn.addEventListener("mouseleave", () => { xTo(0); yTo(0); });
    }
});

/*=========================================================
  HERO PHOTO
  The photo is fixed in place. It only tilts a little while
  the pointer is over the orbit, and returns to flat when the
  pointer leaves. It never reacts to page scroll.
=========================================================*/
(function avatarTilt() {
    const stage = $("#orbit-stage"), avatar = $("#avatar");
    if (!stage || !avatar || !hasGSAP || !finePointer || reduceMotion) return;
    gsap.set(avatar, { transformPerspective: 900 });
    const rx = gsap.quickTo(avatar, "rotationX", { duration: 0.7, ease: "power3.out" });
    const ry = gsap.quickTo(avatar, "rotationY", { duration: 0.7, ease: "power3.out" });
    stage.addEventListener("pointermove", e => {
        const r = stage.getBoundingClientRect();
        const px = (e.clientX - r.left) / r.width - 0.5;
        const py = (e.clientY - r.top) / r.height - 0.5;
        ry(px * 16);
        rx(-py * 16);
    });
    stage.addEventListener("pointerleave", () => { rx(0); ry(0); });
})();

/*=========================================================
  THREE.JS AMBIENT BACKGROUND
=========================================================*/
(function backgroundScene() {
    const canvas = $("#bg-canvas");
    if (!canvas || typeof THREE === "undefined") return;

    const small = window.innerWidth < 768;
    let w = window.innerWidth, h = window.innerHeight;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, w / h, 0.1, 100);
    camera.position.z = 9;

    let renderer;
    try { renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: !small }); }
    catch (e) { return; } // no WebGL: the CSS background still looks fine
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, small ? 1.5 : 2));
    renderer.setSize(w, h, false);

    const group = new THREE.Group();
    scene.add(group);

    const wire = (geo, color, opacity, pos) => {
        const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, wireframe: true, transparent: true, opacity }));
        m.position.set(...pos);
        group.add(m);
        return m;
    };
    const core = wire(new THREE.IcosahedronGeometry(2.1, 1), 0x00c2ff, 0.16, [3.4, 1, 0]);
    const core2 = wire(new THREE.OctahedronGeometry(1.3, 0), 0xffb648, 0.13, [-4, -1.6, -2]);
    const knot = wire(new THREE.TorusKnotGeometry(0.9, 0.28, 100, 12), 0x8b7dff, 0.14, [0.5, -2.6, -4]);

    // soft glow behind the main shape
    const c = document.createElement("canvas");
    c.width = c.height = 256;
    const ctx = c.getContext("2d");
    const grad = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
    grad.addColorStop(0, "rgba(0,194,255,0.55)");
    grad.addColorStop(0.5, "rgba(0,194,255,0.12)");
    grad.addColorStop(1, "rgba(0,194,255,0)");
    ctx.fillStyle = grad; ctx.fillRect(0, 0, 256, 256);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), transparent: true, opacity: 0.7, depthWrite: false, blending: THREE.AdditiveBlending }));
    glow.scale.set(7, 7, 1);
    glow.position.copy(core.position);
    group.add(glow);

    // particle dust
    const count = small ? 110 : 240;
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
        pos[i * 3] = (Math.random() - 0.5) * 20;
        pos[i * 3 + 1] = (Math.random() - 0.5) * 12;
        pos[i * 3 + 2] = (Math.random() - 0.5) * 10;
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0x8b7dff, size: 0.03, transparent: true, opacity: 0.5 }));
    group.add(stars);

    let tx = 0, ty = 0;
    window.addEventListener("mousemove", e => {
        tx = (e.clientX / window.innerWidth - 0.5) * 0.4;
        ty = (e.clientY / window.innerHeight - 0.5) * 0.4;
    });

    let scrollFactor = 0;
    if (hasGSAP) {
        ScrollTrigger.create({
            trigger: document.body, start: "top top", end: "bottom bottom", scrub: 0.8,
            onUpdate: self => { scrollFactor = self.progress * 3.4; }
        });
    } else {
        window.addEventListener("scroll", () => { scrollFactor = window.scrollY / (window.innerHeight * 1.2); }, { passive: true });
    }

    function frame() {
        if (!document.hidden) {
            core.rotation.y += 0.0018; core.rotation.x += 0.0007;
            core2.rotation.y -= 0.0014; core2.rotation.x += 0.001;
            knot.rotation.x += 0.0012; knot.rotation.y += 0.0016;
            stars.rotation.y += 0.0004;
            group.position.y = -scrollFactor * 2.2;
            group.rotation.y += (tx - group.rotation.y) * 0.03;
            group.rotation.x += (ty - group.rotation.x) * 0.03;
            camera.position.z = 9 - scrollFactor * 0.6;
            renderer.render(scene, camera);
        }
        if (!reduceMotion) requestAnimationFrame(frame);
    }
    frame();

    window.addEventListener("resize", () => {
        w = window.innerWidth; h = window.innerHeight;
        camera.aspect = w / h; camera.updateProjectionMatrix();
        renderer.setSize(w, h, false);
        if (reduceMotion) renderer.render(scene, camera);
    });
})();

